# One container behind the existing reverse proxy; no ports are published.
# Set RESURGO_RUNS_DIR to the host directory that holds the run records.
services:
  resurgo-web:
    build:
      context: ..
      dockerfile: Dockerfile
    restart: unless-stopped
    volumes:
      - ${RESURGO_RUNS_DIR:?set RESURGO_RUNS_DIR to the runs directory}:/runs:ro
    networks:
      - public_proxy

networks:
  public_proxy:
    external: true
# Resurgo web: the built React app and the read-only runs API in one container.
# Build from the repo root: docker build -t resurgo-web .

# 1. Build web/ to static files.
FROM node:22-slim AS web
WORKDIR /src/web
COPY web/package.json web/package-lock.json ./
RUN npm ci
COPY web/ ./
RUN npm run build

# 2. The API: fastapi and uvicorn at the versions locked in uv.lock, nothing else from the project.
FROM python:3.12-slim
ENV PYTHONDONTWRITEBYTECODE=1 \
    PYTHONUNBUFFERED=1 \
    RUNS_DIR=/runs

WORKDIR /app

# uv only turns uv.lock into a constraints file; the two packages are then installed under it, so
# their dependencies come in at the locked versions and the rest of the project (langgraph, ...) does not.
COPY pyproject.toml uv.lock ./
RUN pip install --no-cache-dir uv \
 && uv export --frozen --no-dev --no-emit-project --no-hashes -o /tmp/constraints.txt \
 && uv pip install --system --no-cache -c /tmp/constraints.txt fastapi uvicorn \
 && pip uninstall -y uv \
 && rm -f /tmp/constraints.txt pyproject.toml uv.lock

COPY api/ ./api/
COPY --from=web /src/web/dist ./web/dist

RUN useradd --system --uid 10001 --no-create-home resurgo
USER resurgo

EXPOSE 8000
CMD ["uvicorn", "api.main:app", "--host", "REDACTED", "--port", "8000"]
import { useEffect, useState, type ReactNode } from "react";
import { BrowserRouter, Link, NavLink, Route, Routes, useLocation } from "react-router-dom";
import { BackgroundArt } from "@/components/art";
import { ErrorBoundary } from "@/components/ErrorBoundary";
import { ThemeToggle } from "@/components/ThemeToggle";
import { LIFT_EVENT } from "@/lib/beat";
import { useTheme } from "@/lib/theme";
import { Logo } from "@/components/Logo";
import { INSTALL_URL } from "@/lib/utils";
import Landing from "@/pages/Landing";
import RunView from "@/pages/RunView";
import Runs from "@/pages/Runs";

function ScrollToTop() {
  const { pathname } = useLocation();
  useEffect(() => window.scrollTo(0, 0), [pathname]);
  return null;
}

/** A route change: the new page rises in with the shared entrance easing. */
function RouteStage({ children }: { children: ReactNode }) {
  const { pathname } = useLocation();
  return (
    <div key={pathname} className="route-enter">
      {children}
    </div>
  );
}

function Header() {
  const theme = useTheme();
  // The one flourish: the wordmark lifts when a replayed run verifies (see lib/beat.ts).
  const [lifted, setLifted] = useState(false);
  useEffect(() => {
    let id = 0;
    const on = () => {
      setLifted(true);
      window.clearTimeout(id);
      id = window.setTimeout(() => setLifted(false), 560);
    };
    window.addEventListener(LIFT_EVENT, on);
    return () => {
      window.removeEventListener(LIFT_EVENT, on);
      window.clearTimeout(id);
    };
  }, []);
  const link = ({ isActive }: { isActive: boolean }) =>
    `rounded px-1 py-1 text-sm font-semibold underline-offset-8 hover:text-foreground ${isActive ? "text-foreground underline" : "text-muted-foreground"}`;
  return (
    <header className="sticky top-0 z-30 border-b border-border bg-background/85 backdrop-blur">
      <div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-4 sm:px-6">
        <Link to="/" aria-label="Resurgo, home" className="flex items-center">
          {/* The brand's lifted-r wordmark; the file is chosen for the background it sits on. */}
          <img
            src={theme === "dark" ? "/brand/logo-wordmark-dark.svg" : "/brand/logo-wordmark-light.svg"}
            alt="resurgo"
            width={120}
            height={28}
            className={`h-7 w-auto ${lifted ? "lift" : ""}`}
          />
        </Link>
        <nav aria-label="Main" className="flex items-center gap-4 sm:gap-6">
          <NavLink to="/runs" className={link}>Runs</NavLink>
          <a
            href={INSTALL_URL}
            className="press inline-flex min-h-9 items-center gap-2 rounded-lg border border-accent-strong bg-accent-strong px-3 text-sm font-semibold text-on-accent hover:opacity-90"
          >
            <Logo name="github" size="1.25em" decorative />
            <span>Install<span className="hidden sm:inline">{" on GitHub"}</span></span>
          </a>
          <ThemeToggle />
        </nav>
      </div>
    </header>
  );
}

function Footer() {
  return (
    <footer className="border-t border-border">
