const STRIP = ["Node.js", "pnpm", "npm", "Yarn", "Foundry", "Cargo (Rust)", "Docker", "GitHub"];
const BUILT_ON = "Built on neatlogs tracing and Entire checkpoints.";
const logoOk = (l) => l.role === "img" && l.name && l.title === l.name && l.w >= 12 && l.h >= 8 && l.masked;

